"""Independent reference implementation used only for development cross-checks.

Deliberately written differently from submission/main.py: brute force joint
enumeration for inference and explicit type-sequence enumeration for `full`.
"""
import itertools
import json
from fractions import Fraction

G = {('c2p','c2p'):'c2p', ('c2p','p2p'):'c2p', ('c2p','p2c'):'p2p',
     ('p2p','c2p'):'p2p', ('p2p','p2p'):'p2p', ('p2p','p2c'):'p2c',
     ('p2c','c2p'):'p2p', ('p2c','p2p'):'p2p', ('p2c','p2c'):'p2c'}
INV = {'c2p':'p2c', 'p2p':'p2p', 'p2c':'c2p'}
TYPES = ('c2p','p2p','p2c')


def normalise(path, ixps):
    step = [a for a in path if a not in ixps]
    out = []
    for a in step:
        if not out or out[-1] != a:
            out.append(a)
    return out


def aggregate(rib, ixps):
    agg = {}
    for rec in rib:
        p = normalise(rec['path'], ixps)
        if len(p) < 2:
            continue
        if len(set(p)) != len(p):
            continue
        agg[tuple(p)] = agg.get(tuple(p), 0) + rec['count']
    return agg


def links_of(path):
    return set((min(path[i], path[i+1]), max(path[i], path[i+1]))
               for i in range(len(path)-1))


def peel(paths):
    rounds = {}
    current = dict(paths)
    r = 0
    while True:
        occ = {}
        for p in current:
            for i in range(len(p)-1):
                e = (min(p[i], p[i+1]), max(p[i], p[i+1]))
                occ.setdefault(e, []).append(p)
        marked = set()
        for e, ps in occ.items():
            for endpoint in e:
                if all((p[0] == endpoint or p[-1] == endpoint) for p in ps):
                    marked.add(e)
                    break
        if not marked:
            break
        r += 1
        for e in marked:
            rounds[e] = r
        nxt = {}
        for p, c in current.items():
            f = (min(p[0], p[1]), max(p[0], p[1]))
            l = (min(p[-2], p[-1]), max(p[-2], p[-1]))
            lo = 1 if f in marked else 0
            hi = len(p) - (1 if l in marked else 0)
            q = p[lo:hi]
            if len(q) >= 2:
                nxt[q] = nxt.get(q, 0) + c
        current = nxt
    return current, rounds


def context_types(path, pos, edge):
    """Return (L, R) where L/R are ('const', type) or ('var', link, flipped)."""
    u, v = edge
    n = len(path)
    oriented = path if path[pos] == u else path[::-1]
    idx = oriented.index(u) if oriented[pos] == u else (n-2-pos)
    # oriented traversal: u then v
    j = idx
    if j == 0:
        L = ('const', 'c2p')
    else:
        x, y = oriented[j-1], oriented[j]
        L = ('var', (min(x,y), max(x,y)), x > y)
    if j+2 >= n:
        R = ('const', 'p2c')
    else:
        y, z = oriented[j+1], oriented[j+2]
        R = ('var', (min(y,z), max(y,z)), y > z)
    return L, R


def marginals(core_paths):
    core = set()
    for p in core_paths:
        core |= links_of(p)
    core = sorted(core)
    occ = {e: [] for e in core}
    for p, c in core_paths.items():
        for i in range(len(p)-1):
            e = (min(p[i], p[i+1]), max(p[i], p[i+1]))
            L, R = context_types(p, i, e)
            occ[e].append((c, L, R))
    def resolve(spec, assign):
        if spec[0] == 'const':
            return spec[1]
        state = assign[spec[1]]
        return INV[state] if spec[2] else state
    Z = 0
    num = {e: [0, 0, 0] for e in core}
    for combo in itertools.product(TYPES, repeat=len(core)):
        assign = dict(zip(core, combo))
        w = 1
        for e in core:
            phi = [0, 0, 0]
            for c, L, R in occ[e]:
                g = G[(resolve(L, assign), resolve(R, assign))]
                phi[TYPES.index(g)] += c
            w *= phi[TYPES.index(assign[e])]
        Z += w
        for e in core:
            num[e][TYPES.index(assign[e])] += w
    if Z == 0:
        return core, None, 0
    marg = {e: [Fraction(v, Z) for v in num[e]] for e in core}
    return core, marg, Z


def score(path, declared, marg, priors):
    vecs = []
    for i in range(len(path)-1):
        u, v = path[i], path[i+1]
        key = (min(u,v), max(u,v))
        if key in declared:
            vec = declared[key]
        elif key in marg:
            vec = marg[key]
        elif key in priors:
            vec = priors[key]
        else:
            vec = [Fraction(1,3)]*3
        if u > v:
            vec = [vec[2], vec[1], vec[0]]
        vecs.append(vec)
    if len(vecs) < 2:
        return Fraction(1), Fraction(1), None
    triples = []
    for i in range(len(vecs)-1):
        U = vecs[i][0]; D = vecs[i+1][2]
        triples.append(U + D - U*D)
    score = min(triples)
    witness = triples.index(score)
    # full: explicit enumeration of all type sequences
    total = Fraction(0)
    n = len(vecs)
    for combo in itertools.product(TYPES, repeat=n):
        ok = False
        # form c2p* p2c*
        i = 0
        while i < n and combo[i] == 'c2p':
            i += 1
        if all(combo[j] == 'p2c' for j in range(i, n)):
            ok = True
        # form c2p* p2p p2c*
        if not ok:
            i = 0
            while i < n and combo[i] == 'c2p':
                i += 1
            if i < n and combo[i] == 'p2p' and all(combo[j] == 'p2c' for j in range(i+1, n)):
                ok = True
        if ok:
            w = Fraction(1)
            for j, t in enumerate(combo):
                w *= vecs[j][TYPES.index(t)]
            total += w
    return score, total, witness


def run(doc):
    ixps = set(doc['ixps'])
    priors = {}
    for rec in doc['priors']:
        u, v = rec['link']
        s = sum(rec['weights'])
        p = [Fraction(w, s) for w in rec['weights']]
        if u > v:
            p = [p[2], p[1], p[0]]
        priors[(min(u,v), max(u,v))] = p
    declared = {}
    for rec in doc['declared']:
        u, v = rec['link']
        p = [Fraction(0)]*3
        p[TYPES.index(rec['rel'])] = Fraction(1)
        if u > v:
            p = [p[2], p[1], p[0]]
        declared[(min(u,v), max(u,v))] = p
    agg = aggregate(doc['rib'], ixps)
    all_links = set()
    for p in agg:
        all_links |= links_of(p)
    core_paths, rounds = peel(agg)
    core, marg, Z = marginals(core_paths)
    if marg is None:
        return {'error': 'zero-partition'}
    links = []
    for e in sorted(all_links):
        if e in marg:
            links.append({'link': list(e), 'round': 0,
                          'prob': [float(x) for x in marg[e]]})
        else:
            p = priors.get(e, [Fraction(1,3)]*3)
            links.append({'link': list(e), 'round': rounds.get(e, 0),
                          'prob': [float(x) for x in p]})
    queries = []
    for rec in doc['queries']:
        path = normalise(rec['path'], ixps)
        out = {'id': rec['id'], 'path': list(path)}
        if len(set(path)) != len(path):
            out.update(status='loop', score=None, full=None, witness=None,
                       leaked=None)
        else:
            s, f, w = score(path, declared, marg, priors)
            thr = Fraction(rec['threshold'][0], rec['threshold'][1])
            out.update(status='ok', score=float(s), full=float(f), witness=w,
                       leaked=bool(s < thr))
        queries.append(out)
    return {'version': 1, 'links': links, 'queries': queries}
PYEOF
